begin;
-- Aggregate control-plane monitoring. Never expose customer records, amounts or provider identifiers.
create function tenant_private.admin_operations_overview(p_stores uuid[]) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare r jsonb;summary jsonb;details jsonb;live boolean;
begin
 if not coalesce(saas_private.is_operator(),false) then raise exception 'Operator required' using errcode='42501';end if;
 if p_stores is null or cardinality(p_stores)>100 or array_position(p_stores,null::uuid) is not null then raise exception 'Invalid page' using errcode='22023';end if;
 select live_enabled into live from tenant_private.billing_configuration where singleton;
 with states as (
 select w.store_id,sub.state,sub.valid_until,p.shard_code,
 (s.state='provisioning' and s.project_ref is null and s.origin is null and sh.state='local' and sub.valid_until>now() and (sub.state='trial' or (sub.state='active' and live and exists(select 1 from tenant_private.payment_bindings b join tenant_private.paid_periods pp on pp.store_id=b.store_id and pp.provider=b.provider and pp.account_id=b.account_id and pp.plan_code=b.plan_code where b.store_id=w.store_id and b.enabled and b.plan_code=sub.plan_code and pp.state='paid' and pp.period_start<=now() and pp.period_end>now() and pp.period_end>=sub.valid_until)))) licensed
 from tenant_private.workspaces w join public.saas_stores s on s.id=w.store_id left join public.saas_subscriptions sub on sub.store_id=w.store_id left join tenant_private.placements p on p.store_id=w.store_id left join tenant_private.shards sh on sh.code=p.shard_code
 ) select jsonb_build_object('shared',count(*),'licensed',count(*) filter(where licensed),'trials',count(*) filter(where licensed and state='trial'),'paid',count(*) filter(where licensed and state='active'),'blocked',count(*) filter(where not coalesce(licensed,false)),'expiring',count(*) filter(where licensed and valid_until<=now()+interval '7 days'),'pending_domains',(select count(*) from tenant_private.custom_domains where state='pending'),'active_domains',(select count(*) from tenant_private.custom_domains where state='active'),'queued_recovery',(select count(*) from tenant_private.shared_recovery_requests where state='queued'),'planned_releases',(select count(*) from tenant_private.shared_release_plans where state='planned'),'local_shards',(select count(*) from tenant_private.shards where state='local'),'verified_shards',(select count(*) from tenant_private.shards sh where sh.state='local' and exists(select 1 from tenant_private.shared_backup_evidence e where e.shard_code=sh.code and tenant_private.shared_verified_backup(sh.code,e.id)))) into summary from states;
 select coalesce(jsonb_agg(jsonb_build_object('id',w.store_id,'shard',p.shard_code,'licensed',tenant_private.shared_licensed(w.store_id),'storefront_active',tenant_private.storefront_active(w.store_id),'domain_state',coalesce((select state from tenant_private.custom_domains d where d.store_id=w.store_id and d.state in ('pending','active')),'none'),'pending_orders',(select count(*) from public.mt_online_orders o where o.store_id=w.store_id and o.state='pending'),'dispatched_orders',(select count(*) from public.mt_online_orders o where o.store_id=w.store_id and o.state='pending' and o.delivery_state='dispatched'),'backup_verified',exists(select 1 from tenant_private.shared_backup_evidence e where e.shard_code=p.shard_code and tenant_private.shared_verified_backup(p.shard_code,e.id))) order by w.store_id),'[]'::jsonb) into details from tenant_private.workspaces w left join tenant_private.placements p on p.store_id=w.store_id where w.store_id=any(p_stores);
 return jsonb_build_object('as_of',now(),'live_billing_enabled',coalesce(live,false),'summary',summary,'stores',details);
end $$;
create function public.mt_admin_operations_overview(p_stores uuid[]) returns jsonb language sql stable security invoker set search_path='' as $$select tenant_private.admin_operations_overview(p_stores)$$;
revoke all on function tenant_private.admin_operations_overview(uuid[]),public.mt_admin_operations_overview(uuid[]) from public,anon,authenticated,service_role;
grant execute on function tenant_private.admin_operations_overview(uuid[]),public.mt_admin_operations_overview(uuid[]) to authenticated;
commit;